OUT=Path(__file__).resolve().parent
FONT=ImageFont.truetype('/System/Library/Fonts/Hiragino Sans GB.ttc',24)
class Graph:
 def __init__(self,name,title,lanes,h,notes):
  self.name=name; self.title=title; self.h=h;self.lanes=lanes;self.notes=notes;self.nodes={};self.edges=[];self.issues=[]
  self.W=1900; self.centers=[250,720,1190,1660] if len(lanes)==4 else [340,950,1560];self.w=370 if len(lanes)==4 else 460
 def node(self,id,c,y,lines,kind='box',pending=False):
  if isinstance(lines,str):lines=[lines]
  hh=88 if len(lines)==1 else 112;w=self.w
  if kind=='diamond':hh=180;w=310
  self.nodes[id]=dict(x=self.centers[c],y=y,w=w,h=hh,lines=lines,kind=kind,c=c,pending=pending)
  for line in lines:
   if FONT.getlength(line)>(260 if kind=='diamond' else w-38):self.issues.append(f'{id}: {line}')
 def port(self,id,p):
  n=self.nodes[id];x,y,w,h=n['x'],n['y'],n['w'],n['h']
  return dict(top=(x,y-h/2),bottom=(x,y+h/2),left=(x-w/2,y),right=(x+w/2,y))[p]
 def edge(self,a,b,label='',start='bottom',end='top',via=None,lp=None,dash=False):
  A=self.port(a,start);B=self.port(b,end)
  if via:points=[A]+via+[B]
  elif A[0]==B[0] or A[1]==B[1]:points=[A,B]
  else:
   if start in ('left','right') and end in ('left','right'):points=[A,((A[0]+B[0])/2,A[1]),((A[0]+B[0])/2,B[1]),B]
   elif start in ('left','right'):points=[A,(B[0],A[1]),B]
   elif end in ('left','right'):points=[A,(A[0],B[1]),B]
   else:points=[A,(A[0],(A[1]+B[1])/2),(B[0],(A[1]+B[1])/2),B]
  self.edges.append(dict(a=a,b=b,label=label,points=points,lp=lp,dash=dash))
 def chain(self,*ids):
  for a,b in zip(ids,ids[1:]):self.edge(a,b)
 def save(self):
  parts=[f'<svg xmlns="http://www.w3.org/2000/svg" width="1900" height="{self.h}" viewBox="0 0 1900 {self.h}">','<defs><marker id="arrow" markerWidth="12" markerHeight="10" refX="10" refY="5" orient="auto" markerUnits="strokeWidth"><path d="M0 0 L10 5 L0 10 z" fill="#42617D"/></marker></defs>',f'<rect width="1900" height="{self.h}" fill="#FFFFFF"/>']
  def text(x,y,lines,size=24,anchor='middle',weight=500):
   parts.append(f'<text x="{x}" y="{y}" font-size="{size}" fill="#1B3144" text-anchor="{anchor}" font-weight="{weight}">'+''.join(f'<tspan x="{x}" dy="{0 if i==0 else size*1.38}">{html.escape(s)}</tspan>' for i,s in enumerate(lines))+'</text>')
  text(58,70,[self.title],36,'start',700)
  for c,l in enumerate(self.lanes):
   cx=self.centers[c];w=430 if len(self.lanes)==4 else 550
   parts.append(f'<rect x="{cx-w/2}" y="125" width="{w}" height="88" rx="14" fill="{["#F3F7FB","#F1F7F4","#FBF6EC","#F3F7FB"][c]}"/>')
   text(cx,171,[l],24,weight=700)
   parts.append(f'<line x1="{cx-w/2}" y1="225" x2="{cx-w/2}" y2="{self.h-175}" stroke="#D8E3EA" stroke-width="2"/>')
  for e in self.edges:
   pts=' '.join(f'{x:g},{y:g}' for x,y in e['points']);dash=' stroke-dasharray="8 6"' if e['dash'] else ''
   parts.append(f'<polyline points="{pts}" fill="none" stroke="#42617D" stroke-width="2.8" marker-end="url(#arrow)"{dash}/>')
  for id,n in self.nodes.items():
   x,y,w,h=n['x'],n['y'],n['w'],n['h'];fill='#FFF1CD' if n['pending'] else ['#DCECF6','#DCEEE3','#F7E8C9','#DCECF6'][n['c']]
   if n['kind']=='diamond':parts.append(f'<rect x="-90" y="-90" width="180" height="180" fill="{fill}" stroke="#678198" stroke-width="2" transform="translate({x},{y}) scale(1.22,0.71) rotate(45)"/>')
   else:parts.append(f'<rect x="{x-w/2}" y="{y-h/2}" width="{w}" height="{h}" rx="11" fill="{fill}" stroke="#678198" stroke-width="2"/>')
   text(x,y-(len(n['lines'])-1)*16+8,n['lines'])
  for e in self.edges:
   if e['label']:
    if e['lp']:x,y=e['lp']
    else:
     p,q=max(zip(e['points'],e['points'][1:]),key=lambda v:abs(v[0][0]-v[1][0])+abs(v[0][1]-v[1][1]));x=(p[0]+q[0])/2;y=(p[1]+q[1])/2-10
    ww=max(48,FONT.getlength(e['label'])+22)
    parts.append(f'<rect x="{x-ww/2}" y="{y-22}" width="{ww}" height="31" rx="4" fill="#FFFFFF"/>');text(x,y,[e['label']],21)
  text(58,self.h-111,self.notes,22,'start',400)
  parts.append('</svg>');svg=OUT/(self.name+'.svg');svg.write_text('\n'.join(parts),encoding='utf8')
  subprocess.run(['rsvg-convert','-o',str(OUT/(self.name+'.png')),str(svg)],check=True)
  return dict(file=self.name,nodes=len(self.nodes),decisions=sum(n['kind']=='diamond' for n in self.nodes.values()),connections=len(self.edges),overflow=self.issues)
